 74		rec := a.do("POST", "/payments", `{"merchant_id":"m_1","amount":"100.00","currency":"USD"}`)
 75		if rec.Code != http.StatusCreated {
 76			t.Fatalf("status %d: %s", rec.Code, rec.Body)
