  1	package money
  2	
  3	import (
  4		"errors"
  5		"fmt"
  6		"math"
  7		"strconv"
  8		"strings"
  9	)
 10	
 11	var (
 12		// ErrInvalidAmount is returned for malformed or out-of-range amounts.
 13		ErrInvalidAmount = errors.New("invalid amount")
 14		// ErrPrecision is returned when an amount has more decimals than its currency allows.
 15		ErrPrecision = errors.New("too many decimal places for currency")
 16		// ErrCurrencyMismatch is returned when combining amounts in different currencies.
 17		ErrCurrencyMismatch = errors.New("currency mismatch")
 18	)
 19	
 20	// Amount is an exact quantity of money in minor units.
 21	type Amount struct {
 22		Minor    int64
 23		Currency Currency
 24	}
 25	
 26	// New builds an amount from minor units.
 27	func New(minor int64, code string) (Amount, error) {
 28		c, err := LookupCurrency(code)
 29		if err != nil {
 30			return Amount{}, err
 31		}
 32		return Amount{Minor: minor, Currency: c}, nil
 33	}
 34	
 35	// MustNew is New for tests and constants; it panics on unknown currencies.
 36	func MustNew(minor int64, code string) Amount {
 37		a, err := New(minor, code)
 38		if err != nil {
 39			panic(err)
 40		}
 41		return a
 42	}
 43	
 44	// Parse reads a decimal string in major units ("10.50") for the given currency.
 45	// More fractional digits than the currency exponent is an error, never rounded.
 46	func Parse(s, code string) (Amount, error) {
 47		cur, err := LookupCurrency(code)
 48		if err != nil {
 49			return Amount{}, err
 50		}
 51		s = strings.TrimSpace(s)
 52		neg := strings.HasPrefix(s, "-")
 53		s = strings.TrimPrefix(s, "-")
 54		intPart, frac, hasDot := strings.Cut(s, ".")
 55		if intPart == "" || (hasDot && frac == "") || !digits(intPart) || !digits(frac) {
 56			return Amount{}, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
 57		}
 58		if len(frac) > cur.Exponent {
 59			return Amount{}, fmt.Errorf("%w: %s allows %d, got %q", ErrPrecision, cur.Code, cur.Exponent, s)
 60		}
 61		major, err := strconv.ParseInt(intPart, 10, 64)
 62		if err != nil || major > math.MaxInt64/cur.Factor() {
 63			return Amount{}, fmt.Errorf("%w: %q out of range", ErrInvalidAmount, s)
 64		}
 65		minor := major * cur.Factor()
 66		if frac != "" {
 67			frac += strings.Repeat("0", cur.Exponent-len(frac))
 68			f, err := strconv.ParseInt(frac, 10, 64)
 69			if err != nil {
 70				return Amount{}, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
 71			}
 72			minor += f
 73		}
 74		if neg {
 75			minor = -minor
 76		}
 77		return Amount{Minor: minor, Currency: cur}, nil
 78	}
 79	
 80	func digits(s string) bool {
 81		for _, r := range s {
 82			if r < '0' || r > '9' {
 83				return false
 84			}
 85		}
 86		return true
 87	}
 88	
 89	// Decimal renders the amount in major units with exactly Exponent decimals.
 90	func (a Amount) Decimal() string {
 91		m := a.Minor
 92		sign := ""
 93		if m < 0 {
 94			sign = "-"
 95			m = -m
 96		}
 97		if a.Currency.Exponent == 0 {
 98			return sign + strconv.FormatInt(m, 10)
 99		}
100		f := a.Currency.Factor()
101		return fmt.Sprintf("%s%d.%0*d", sign, m/f, a.Currency.Exponent, m%f)
102	}
103	
104	// String renders "10.50 USD".
105	func (a Amount) String() string { return a.Decimal() + " " + a.Currency.Code }
106	
107	// Add returns a+b; both must share a currency.
108	func (a Amount) Add(b Amount) (Amount, error) {
109		if a.Currency != b.Currency {
110			return Amount{}, fmt.Errorf("%w: %s + %s", ErrCurrencyMismatch, a.Currency.Code, b.Currency.Code)
111		}
112		return Amount{Minor: a.Minor + b.Minor, Currency: a.Currency}, nil
113	}
114	
115	// Sub returns a-b; both must share a currency.
116	func (a Amount) Sub(b Amount) (Amount, error) {
117		if a.Currency != b.Currency {
118			return Amount{}, fmt.Errorf("%w: %s - %s", ErrCurrencyMismatch, a.Currency.Code, b.Currency.Code)
119		}
120		return Amount{Minor: a.Minor - b.Minor, Currency: a.Currency}, nil
121	}
122	
123	// IsPositive reports whether the amount is strictly greater than zero.
124	func (a Amount) IsPositive() bool { return a.Minor > 0 }

  1	package payment
  2	
  3	import (
  4		"context"
  5		"fmt"
  6		"sync"
  7	
  8		"example.com/gopayments/clock"
  9		"example.com/gopayments/money"
 10	)
 11	
 12	// IDGenerator creates unique identifiers with a type prefix.
 13	type IDGenerator interface {
 14		NewID(prefix string) string
 15	}
 16	
 17	// SeqIDs is a deterministic IDGenerator ("pay_000001", "ref_000002", ...).
 18	type SeqIDs struct {
 19		mu sync.Mutex
 20		n  int
 21	}
 22	
 23	// NewSeqIDs returns a sequential generator starting at 1.
 24	func NewSeqIDs() *SeqIDs { return &SeqIDs{} }
 25	
 26	// NewID returns the next identifier.
 27	func (g *SeqIDs) NewID(prefix string) string {
 28		g.mu.Lock()
 29		defer g.mu.Unlock()
 30		g.n++
 31		return fmt.Sprintf("%s_%06d", prefix, g.n)
 32	}
 33	
 34	// Config tunes the service.
 35	type Config struct {
 36		// FeeBps is the processing fee in basis points charged on every payment.
 37		FeeBps int64
 38	}
 39	
 40	// Service drives the payment lifecycle.
 41	type Service struct {
 42		repo   Repository
 43		clock  clock.Clock
 44		ids    IDGenerator
 45		events Publisher
 46		cfg    Config
 47	}
 48	
 49	// NewService wires a Service. events may be nil.
 50	func NewService(repo Repository, clk clock.Clock, ids IDGenerator, events Publisher, cfg Config) *Service {
 51		return &Service{repo: repo, clock: clk, ids: ids, events: events, cfg: cfg}
 52	}
 53	
 54	// CreateInput is the input of Create.
 55	type CreateInput struct {
 56		MerchantID string
 57		Amount     money.Amount
 58	}
 59	
 60	// Create registers a new payment in status CREATED.
 61	func (s *Service) Create(ctx context.Context, in CreateInput) (Payment, error) {
 62		if in.MerchantID == "" {
 63			return Payment{}, fmt.Errorf("%w: merchant id is required", ErrInvalidInput)
 64		}
 65		if !in.Amount.IsPositive() {
 66			return Payment{}, fmt.Errorf("%w: amount must be positive, got %s", ErrInvalidInput, in.Amount)
 67		}
 68		fee, err := money.Fee(in.Amount, s.cfg.FeeBps)
 69		if err != nil {
 70			return Payment{}, fmt.Errorf("compute fee: %w", err)
 71		}
 72		now := s.clock.Now()
 73		p := Payment{
 74			ID:         s.ids.NewID("pay"),
 75			MerchantID: in.MerchantID,
 76			Amount:     in.Amount,
 77			Fee:        fee,
 78			Status:     StatusCreated,
 79			Version:    1,
 80			CreatedAt:  now,
 81			UpdatedAt:  now,
 82		}
 83		if err := s.repo.Create(ctx, p); err != nil {
 84			return Payment{}, fmt.Errorf("create payment: %w", err)
 85		}
 86		s.publish(ctx, Event{Type: "payment.created", Payment: p})
 87		return p, nil
 88	}
 89	
 90	// Get loads a payment.
 91	func (s *Service) Get(ctx context.Context, id string) (Payment, error) {
 92		p, err := s.repo.Get(ctx, id)
 93		if err != nil {
 94			return Payment{}, fmt.Errorf("get payment %s: %w", id, err)
 95		}
 96		return p, nil
 97	}
 98	
 99	// List returns one page of a merchant's payments.
100	func (s *Service) List(ctx context.Context, merchantID string, page Page) ([]Payment, string, error) {
101		if merchantID == "" {
102			return nil, "", fmt.Errorf("%w: merchant id is required", ErrInvalidInput)
103		}
104		ps, next, err := s.repo.ListByMerchant(ctx, merchantID, page)
105		if err != nil {
106			return nil, "", fmt.Errorf("list payments of %s: %w", merchantID, err)
107		}
108		return ps, next, nil
109	}
110	
111	// Authorize moves a CREATED payment to PENDING (sent to the provider).
112	func (s *Service) Authorize(ctx context.Context, id string) (Payment, error) {
113		return s.mutate(ctx, id, func(p *Payment) (Event, error) {
114			switch p.Status {
115			case StatusCreated:
116				p.Status = StatusPending
117				return Event{Type: "payment.pending"}, nil
118			default:
119				return Event{}, fmt.Errorf("%w: cannot authorize a %s payment", ErrInvalidTransition, p.Status)
120			}
121		})
122	}
123	
124	// Capture moves a PENDING payment to SUCCEEDED.
125	func (s *Service) Capture(ctx context.Context, id string) (Payment, error) {
126		return s.mutate(ctx, id, func(p *Payment) (Event, error) {
127			switch p.Status {
128			case StatusPending:
129				p.Status = StatusSucceeded
130				return Event{Type: "payment.succeeded"}, nil
131			default:
132				return Event{}, fmt.Errorf("%w: cannot capture a %s payment", ErrInvalidTransition, p.Status)
133			}
134		})
135	}
136	
137	// Decline moves a CREATED or PENDING payment to DECLINED.
138	func (s *Service) Decline(ctx context.Context, id, reason string) (Payment, error) {
139		return s.mutate(ctx, id, func(p *Payment) (Event, error) {
140			switch p.Status {
141			case StatusCreated, StatusPending:
142				p.Status = StatusDeclined
143				p.DeclineReason = reason
144				return Event{Type: "payment.declined"}, nil
145			default:
146				return Event{}, fmt.Errorf("%w: cannot decline a %s payment", ErrInvalidTransition, p.Status)
147			}
148		})
149	}
150	
151	// Refund refunds amount of a SUCCEEDED payment. Partial refunds keep the
152	// payment SUCCEEDED; once the whole amount is refunded it becomes REFUNDED.
153	func (s *Service) Refund(ctx context.Context, id string, amount money.Amount) (Payment, Refund, error) {
154		if !amount.IsPositive() {
155			return Payment{}, Refund{}, fmt.Errorf("%w: refund amount must be positive, got %s", ErrInvalidInput, amount)
156		}
157		var refund Refund
158		p, err := s.mutate(ctx, id, func(p *Payment) (Event, error) {
159			switch p.Status {
160			case StatusSucceeded:
161			default:
162				return Event{}, fmt.Errorf("%w: cannot refund a %s payment", ErrInvalidTransition, p.Status)
163			}
164			if amount.Currency != p.Amount.Currency {
165				return Event{}, fmt.Errorf("%w: refund in %s for a %s payment", money.ErrCurrencyMismatch, amount.Currency.Code, p.Amount.Currency.Code)
166			}
167			if amount.Minor > p.Remaining().Minor {
168				return Event{}, fmt.Errorf("%w: requested %s, remaining %s", ErrRefundExceedsRemaining, amount, p.Remaining())
169			}
170			refund = Refund{ID: s.ids.NewID("ref"), Amount: amount, CreatedAt: s.clock.Now()}
171			p.Refunded += amount.Minor
172			p.Refunds = append(p.Refunds, refund)
173			evType := "payment.partially_refunded"
174			if p.Refunded == p.Amount.Minor {
175				p.Status = StatusRefunded
176				evType = "payment.refunded"
177			}
178			return Event{Type: evType, Refund: &refund}, nil
179		})
180		if err != nil {
181			return Payment{}, Refund{}, err
182		}
183		return p, refund, nil
184	}
185	
186	// mutate loads a payment, applies change and saves it with optimistic locking.
187	func (s *Service) mutate(ctx context.Context, id string, change func(p *Payment) (Event, error)) (Payment, error) {
188		p, err := s.repo.Get(ctx, id)
189		if err != nil {
190			return Payment{}, fmt.Errorf("load payment %s: %w", id, err)
191		}
192		ev, err := change(&p)
193		if err != nil {
194			return Payment{}, fmt.Errorf("payment %s: %w", id, err)
195		}
196		p.UpdatedAt = s.clock.Now()
197		if err := s.repo.Update(ctx, p); err != nil {
198			return Payment{}, fmt.Errorf("save payment %s: %w", id, err)
199		}
200		p.Version++
201		ev.Payment = p
202		s.publish(ctx, ev)
203		return p, nil
204	}
205	
206	func (s *Service) publish(ctx context.Context, ev Event) {
207		if s.events == nil {
208			return
209		}
210		// Delivery is asynchronous and retried by the dispatcher; a failure to
211		// enqueue must not fail the payment operation.
212		_ = s.events.Publish(ctx, ev)
213	}

  1	// Package webhook delivers payment events to merchant endpoints with signed
  2	// payloads, retries with exponential backoff and a dead-letter list.
  3	package webhook
  4	
  5	import (
  6		"context"
  7		"encoding/json"
  8		"fmt"
  9		"net/http"
 10		"sync"
 11		"time"
 12	
 13		"example.com/gopayments/clock"
 14		"example.com/gopayments/payment"
 15	)
 16	
 17	// Event is the webhook payload.
 18	type Event struct {
 19		ID         string          `json:"id"`
 20		Type       string          `json:"type"`
 21		MerchantID string          `json:"merchant_id"`
 22		CreatedAt  time.Time       `json:"created_at"`
 23		Data       json.RawMessage `json:"data"`
 24	}
 25	
 26	// Endpoint is a merchant's webhook destination.
 27	type Endpoint struct {
 28		URL    string
 29		Secret string
 30	}
 31	
 32	// Endpoints resolves the endpoint of a merchant.
 33	type Endpoints interface {
 34		Endpoint(merchantID string) (Endpoint, bool)
 35	}
 36	
 37	// StaticEndpoints is a fixed merchant -> endpoint map.
 38	type StaticEndpoints map[string]Endpoint
 39	
 40	// Endpoint implements Endpoints.
 41	func (s StaticEndpoints) Endpoint(merchantID string) (Endpoint, bool) {
 42		e, ok := s[merchantID]
 43		return e, ok
 44	}
 45	
 46	// Policy controls retries.
 47	type Policy struct {
 48		MaxAttempts int
 49		BaseDelay   time.Duration
 50		MaxDelay    time.Duration
 51	}
 52	
 53	// DefaultPolicy is the production retry policy.
 54	func DefaultPolicy() Policy {
 55		return Policy{MaxAttempts: 6, BaseDelay: time.Second, MaxDelay: 10 * time.Minute}
 56	}
 57	
 58	// Backoff is the wait after failed attempt n (n >= 1): BaseDelay * 2^(n-1),
 59	// capped at MaxDelay.
 60	func (p Policy) Backoff(n int) time.Duration {
 61		d := p.BaseDelay
 62		for i := 1; i < n; i++ {
 63			if d >= p.MaxDelay/2 {
 64				return p.MaxDelay
 65			}
 66			d *= 2
 67		}
 68		return min(d, p.MaxDelay)
 69	}
 70	
 71	// DeadLetter is an event that exhausted its retries or failed permanently.
 72	type DeadLetter struct {
 73		Event      Event
 74		Attempts   int
 75		LastStatus int
 76		LastError  string
 77		FailedAt   time.Time
 78	}
 79	
 80	// Dispatcher queues events and delivers them.
 81	type Dispatcher struct {
 82		sender    Sender
 83		endpoints Endpoints
 84		clock     clock.Clock
 85		policy    Policy
 86	
 87		mu        sync.Mutex
 88		seq       int
 89		queue     []Event
 90		dead      []DeadLetter
 91		delivered int
 92	}
 93	
 94	var _ payment.Publisher = (*Dispatcher)(nil)
 95	
 96	// NewDispatcher wires a dispatcher.
 97	func NewDispatcher(sender Sender, endpoints Endpoints, clk clock.Clock, policy Policy) *Dispatcher {
 98		return &Dispatcher{sender: sender, endpoints: endpoints, clock: clk, policy: policy}
 99	}
100	
101	type paymentData struct {
102		PaymentID string `json:"payment_id"`
103		Status    string `json:"status"`
104		Amount    string `json:"amount"`
105		Currency  string `json:"currency"`
106		Refunded  string `json:"refunded_amount"`
107		RefundID  string `json:"refund_id,omitempty"`
108	}
109	
110	// Publish implements payment.Publisher by queueing a webhook event.
111	func (d *Dispatcher) Publish(_ context.Context, ev payment.Event) error {
112		data := paymentData{
113			PaymentID: ev.Payment.ID,
114			Status:    string(ev.Payment.Status),
115			Amount:    ev.Payment.Amount.Decimal(),
116			Currency:  ev.Payment.Amount.Currency.Code,
117			Refunded:  ev.Payment.RefundedAmount().Decimal(),
118		}
119		if ev.Refund != nil {
120			data.RefundID = ev.Refund.ID
121		}
122		raw, err := json.Marshal(data)
123		if err != nil {
124			return fmt.Errorf("encode %s event: %w", ev.Type, err)
125		}
126		d.mu.Lock()
127		defer d.mu.Unlock()
128		d.seq++
129		d.queue = append(d.queue, Event{
130			ID:         fmt.Sprintf("evt_%06d", d.seq),
131			Type:       ev.Type,
132			MerchantID: ev.Payment.MerchantID,
133			CreatedAt:  d.clock.Now(),
134			Data:       raw,
135		})
136		return nil
137	}
138	
139	// Pending returns the number of queued, undelivered events.
140	func (d *Dispatcher) Pending() int {
141		d.mu.Lock()
142		defer d.mu.Unlock()
143		return len(d.queue)
144	}
145	
146	// Delivered returns how many events were delivered successfully.
147	func (d *Dispatcher) Delivered() int {
148		d.mu.Lock()
149		defer d.mu.Unlock()
150		return d.delivered
151	}
152	
153	// DeadLetters returns a snapshot of the dead-letter list.
154	func (d *Dispatcher) DeadLetters() []DeadLetter {
155		d.mu.Lock()
156		defer d.mu.Unlock()
157		return append([]DeadLetter(nil), d.dead...)
158	}
159	
160	// Flush delivers every queued event. It returns early only if ctx is done;
161	// undelivered events stay queued in that case.
162	func (d *Dispatcher) Flush(ctx context.Context) error {
163		d.mu.Lock()
164		batch := d.queue
165		d.queue = nil
166		d.mu.Unlock()
167	
168		for i, ev := range batch {
169			if err := d.deliver(ctx, ev); err != nil {
170				d.mu.Lock()
171				d.queue = append(append([]Event(nil), batch[i:]...), d.queue...)
172				d.mu.Unlock()
173				return fmt.Errorf("flush webhooks: %w", err)
174			}
175		}
176		return nil
177	}
178	
179	// deliver attempts ev until success, a permanent failure or MaxAttempts.
180	// It only returns an error when ctx is done.
181	func (d *Dispatcher) deliver(ctx context.Context, ev Event) error {
182		ep, ok := d.endpoints.Endpoint(ev.MerchantID)
183		if !ok {
184			return nil // merchant has no webhook configured
185		}
186		body, err := json.Marshal(ev)
187		if err != nil {
188			d.deadLetter(ev, 0, 0, fmt.Errorf("encode event: %w", err))
189			return nil
190		}
191		var (
192			status  int
193			sendErr error
194			attempt int
195		)
196		for attempt = 1; attempt <= d.policy.MaxAttempts; attempt++ {
197			headers := map[string]string{
198				"Content-Type":  "application/json",
199				"Webhook-Id":    ev.ID,
200				SignatureHeader: Sign(ep.Secret, d.clock.Now().Unix(), body),
201			}
202			status, sendErr = d.sender.Send(ctx, Delivery{EventID: ev.ID, URL: ep.URL, Body: body, Headers: headers, Attempt: attempt})
203			if sendErr == nil && status >= 200 && status < 300 {
204				d.mu.Lock()
205				d.delivered++
206				d.mu.Unlock()
207				return nil
208			}
209			if !retryable(status, sendErr) || attempt == d.policy.MaxAttempts {
210				break
211			}
212			if err := d.clock.Sleep(ctx, d.policy.Backoff(attempt)); err != nil {
213				return err
214			}
215		}
216		d.deadLetter(ev, attempt, status, sendErr)
217		return nil
218	}
219	
220	func (d *Dispatcher) deadLetter(ev Event, attempts, status int, err error) {
221		dl := DeadLetter{Event: ev, Attempts: attempts, LastStatus: status, FailedAt: d.clock.Now()}
222		if err != nil {
223			dl.LastError = err.Error()
224		}
225		d.mu.Lock()
226		defer d.mu.Unlock()
227		d.dead = append(d.dead, dl)
228	}
229	
230	// retryable reports whether a failed attempt should be retried: transport
231	// errors, 408, 429 and 5xx are transient; any other status is permanent.
232	func retryable(status int, err error) bool {
233		if err != nil {
234			return true
235		}
236		return status == http.StatusRequestTimeout || status == http.StatusTooManyRequests || status >= 500
237	}

