func resolveAmount(amount *string, amountMinor *int64, currency string) (money.Amount, error) {
	switch {
	case amount == nil && amountMinor == nil:
		return money.Amount{}, fmt.Errorf("%w: amount or amount_minor is required", payment.ErrInvalidInput)
	case amount != nil && amountMinor == nil:
		return money.Parse(*amount, currency)
	case amount == nil && amountMinor != nil:
		return money.New(*amountMinor, currency)
	default:
		parsed, err := money.Parse(*amount, currency)
		if err != nil {
			return money.Amount{}, err
		}
		minor, err := money.New(*amountMinor, currency)
		if err != nil {
			return money.Amount{}, err
		}
		if parsed.Minor != minor.Minor {
			return money.Amount{}, fmt.Errorf("%w: amount %q and amount_minor %d do not match", payment.ErrInvalidInput, *amount, *amountMinor)
		}
		return parsed, nil
	}
}

