		{"both mismatch USD", `{"merchant_id":"m","amount":"10.50","amount_minor":1051,"currency":"USD"}`},
		{"both mismatch major vs minor", `{"merchant_id":"m","amount":"10","amount_minor":10,"currency":"USD"}`},
		{"both mismatch JPY", `{"merchant_id":"m","amount":"10","amount_minor":1000,"currency":"JPY"}`},
