		{"unknown field with minor", `{"merchant_id":"m","amount_minor":1050,"currency":"USD","extra":1}`},
		{"integer for legacy amount", `{"merchant_id":"m","amount":1050,"currency":"USD"}`},
	}
	for _, tt := range tests {
