func TestIdempotencyAcrossAmountFormats(t *testing.T) {
	t.Run("create legacy then minor", func(t *testing.T) {
		a := newTestAPI(t)
		first := a.do("POST", "/payments", `{"merchant_id":"m_1","amount":"10.50","currency":"USD"}`, IdempotencyKeyHeader, "k1")
		second := a.do("POST", "/payments", `{"merchant_id":"m_1","amount_minor":1050,"currency":"USD"}`, IdempotencyKeyHeader, "k1")
		third := a.do("POST", "/payments", `{"merchant_id":"m_1","amount":"10.50","amount_minor":1050,"currency":"USD"}`, IdempotencyKeyHeader, "k1")
		if first.Code != http.StatusCreated || second.Code != http.StatusCreated || third.Code != http.StatusCreated {
			t.Fatalf("codes %d %d %d", first.Code, second.Code, third.Code)
		}
		if second.Header().Get(ReplayedHeader) != "true" || first.Body.String() != second.Body.String() {
			t.Fatalf("second not replayed: %s vs %s", first.Body, second.Body)
		}
		if third.Header().Get(ReplayedHeader) != "true" || first.Body.String() != third.Body.String() {
			t.Fatalf("third not replayed: %s vs %s", first.Body, third.Body)
		}
		conflict := a.do("POST", "/payments", `{"merchant_id":"m_1","amount_minor":1051,"currency":"USD"}`, IdempotencyKeyHeader, "k1")
		if conflict.Code != http.StatusUnprocessableEntity {
			t.Fatalf("conflict status %d: %s", conflict.Code, conflict.Body)
		}
	})

	t.Run("create minor then legacy", func(t *testing.T) {
		a := newTestAPI(t)
		first := a.do("POST", "/payments", `{"merchant_id":"m_1","amount_minor":1050,"currency":"USD"}`, IdempotencyKeyHeader, "k2")
		second := a.do("POST", "/payments", `{"merchant_id":"m_1","amount":"10.50","currency":"USD"}`, IdempotencyKeyHeader, "k2")
		if first.Code != http.StatusCreated || second.Code != http.StatusCreated {
			t.Fatalf("codes %d %d", first.Code, second.Code)
		}
		if second.Header().Get(ReplayedHeader) != "true" || first.Body.String() != second.Body.String() {
			t.Fatalf("not replayed: %s vs %s", first.Body, second.Body)
		}
	})

	t.Run("refund legacy then minor and minor then legacy", func(t *testing.T) {
		a := newTestAPI(t)
		p := a.createSucceeded("50.00", "USD")

		r1 := a.do("POST", "/payments/"+p.ID+"/refunds", `{"amount":"10.50"}`, IdempotencyKeyHeader, "rk1")
		r2 := a.do("POST", "/payments/"+p.ID+"/refunds", `{"amount_minor":1050}`, IdempotencyKeyHeader, "rk1")
		if r1.Code != http.StatusCreated || r2.Code != http.StatusCreated {
			t.Fatalf("codes %d %d", r1.Code, r2.Code)
		}
		if r2.Header().Get(ReplayedHeader) != "true" || r1.Body.String() != r2.Body.String() {
			t.Fatalf("refund not replayed: %s vs %s", r1.Body, r2.Body)
		}

		r3 := a.do("POST", "/payments/"+p.ID+"/refunds", `{"amount_minor":500}`, IdempotencyKeyHeader, "rk2")
		r4 := a.do("POST", "/payments/"+p.ID+"/refunds", `{"amount":"5.00"}`, IdempotencyKeyHeader, "rk2")
		if r3.Code != http.StatusCreated || r4.Code != http.StatusCreated {
			t.Fatalf("codes %d %d", r3.Code, r4.Code)
		}
		if r4.Header().Get(ReplayedHeader) != "true" || r3.Body.String() != r4.Body.String() {
			t.Fatalf("second refund not replayed: %s vs %s", r3.Body, r4.Body)
		}

		conflict := a.do("POST", "/payments/"+p.ID+"/refunds", `{"amount":"5.01"}`, IdempotencyKeyHeader, "rk2")
		if conflict.Code != http.StatusUnprocessableEntity {
			t.Fatalf("conflict status %d: %s", conflict.Code, conflict.Body)
		}

		got := decode[paymentResponse](t, a.do("GET", "/payments/"+p.ID, ""))
		if got.RefundedMinor != 1550 || len(got.Refunds) != 2 {
			t.Fatalf("expected 2 refunds totaling 1550, got %+v", got)
		}
	})
}

