func TestCreatePaymentMinorUnits(t *testing.T) {
	tests := []struct {
		name      string
		body      string
		wantDec   string
		wantMinor int64
		wantFee   string
		wantFeeM  int64
		wantCur   string
	}{
		{
			name:      "minor only USD",
			body:      `{"merchant_id":"m_1","amount_minor":1050,"currency":"USD"}`,
			wantDec:   "10.50",
			wantMinor: 1050,
			wantFee:   "0.30",
			wantFeeM:  30,
			wantCur:   "USD",
		},
		{
			name:      "minor only JPY zero exponent",
			body:      `{"merchant_id":"m_1","amount_minor":1500,"currency":"JPY"}`,
			wantDec:   "1500",
			wantMinor: 1500,
			wantFee:   "44",
			wantFeeM:  44,
			wantCur:   "JPY",
		},
		{
			name:      "minor only KWD three exponent",
			body:      `{"merchant_id":"m_1","amount_minor":1250,"currency":"KWD"}`,
			wantDec:   "1.250",
			wantMinor: 1250,
			wantFee:   "0.036",
			wantFeeM:  36,
			wantCur:   "KWD",
		},
		{
			name:      "both matching USD",
			body:      `{"merchant_id":"m_1","amount":"10.50","amount_minor":1050,"currency":"USD"}`,
			wantDec:   "10.50",
			wantMinor: 1050,
			wantFee:   "0.30",
			wantFeeM:  30,
			wantCur:   "USD",
		},
		{
			name:      "both matching shorthand decimal USD",
			body:      `{"merchant_id":"m_1","amount":"10.5","amount_minor":1050,"currency":"USD"}`,
			wantDec:   "10.50",
			wantMinor: 1050,
			wantFee:   "0.30",
			wantFeeM:  30,
			wantCur:   "USD",
		},
		{
			name:      "both matching JPY",
			body:      `{"merchant_id":"m_1","amount":"1500","amount_minor":1500,"currency":"JPY"}`,
			wantDec:   "1500",
			wantMinor: 1500,
			wantFee:   "44",
			wantFeeM:  44,
			wantCur:   "JPY",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			a := newTestAPI(t)
			rec := a.do("POST", "/payments", tt.body)
			if rec.Code != http.StatusCreated {
				t.Fatalf("status %d: %s", rec.Code, rec.Body)
			}
			p := decode[paymentResponse](t, rec)
			if p.Amount != tt.wantDec || p.AmountMinor != tt.wantMinor ||
				p.Fee != tt.wantFee || p.FeeMinor != tt.wantFeeM ||
				p.RefundedAmount != moneyZero(tt.wantCur) || p.RefundedMinor != 0 ||
				p.RemainingAmount != tt.wantDec || p.RemainingMinor != tt.wantMinor ||
				p.Currency != tt.wantCur {
				t.Fatalf("unexpected payment %+v", p)
			}
		})
	}
}

func moneyZero(cur string) string {
	switch cur {
	case "JPY", "CLP":
		return "0"
	case "KWD":
		return "0.000"
	default:
		return "0.00"
	}
}

