func TestRefundMinorUnitsAndValidation(t *testing.T) {
	a := newTestAPI(t)
	p := a.createSucceeded("50.00", "USD")

	badRefunds := []struct {
		name, body string
	}{
		{"neither", `{}`},
		{"mismatch", `{"amount":"10.00","amount_minor":999}`},
		{"empty amount with minor", `{"amount":"","amount_minor":1000}`},
		{"zero minor", `{"amount_minor":0}`},
		{"negative minor", `{"amount_minor":-50}`},
		{"float minor", `{"amount_minor":10.5}`},
		{"string minor", `{"amount_minor":"1000"}`},
		{"unknown field", `{"amount_minor":100,"unknown":true}`},
	}
	for _, tt := range badRefunds {
		t.Run(tt.name, func(t *testing.T) {
			rec := a.do("POST", "/payments/"+p.ID+"/refunds", tt.body)
			if rec.Code != http.StatusBadRequest {
				t.Fatalf("status %d: %s", rec.Code, rec.Body)
			}
			if e := decode[errorBody](t, rec); e.Error.Code != "invalid_request" {
				t.Fatalf("code %q", e.Error.Code)
			}
		})
	}

	// Partial refund via amount_minor.
	rec := a.do("POST", "/payments/"+p.ID+"/refunds", `{"amount_minor":1500}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("refund minor: %d %s", rec.Code, rec.Body)
	}
	got := decode[paymentResponse](t, rec)
	if got.RefundedAmount != "15.00" || got.RefundedMinor != 1500 ||
		got.RemainingAmount != "35.00" || got.RemainingMinor != 3500 ||
		len(got.Refunds) != 1 || got.Refunds[0].Amount != "15.00" || got.Refunds[0].AmountMinor != 1500 {
		t.Fatalf("after partial refund %+v", got)
	}

	// Partial refund via matching amount and amount_minor.
	rec = a.do("POST", "/payments/"+p.ID+"/refunds", `{"amount":"10.00","amount_minor":1000}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("refund both: %d %s", rec.Code, rec.Body)
	}
	got = decode[paymentResponse](t, rec)
	if got.RefundedMinor != 2500 || got.RemainingMinor != 2500 || len(got.Refunds) != 2 || got.Refunds[1].AmountMinor != 1000 {
		t.Fatalf("after second refund %+v", got)
	}

	// Exceeding remaining via amount_minor -> 422.
	rec = a.do("POST", "/payments/"+p.ID+"/refunds", `{"amount_minor":2501}`)
	if rec.Code != http.StatusUnprocessableEntity {
		t.Fatalf("exceed status %d: %s", rec.Code, rec.Body)
	}

	// Full remaining refund via amount_minor.
	rec = a.do("POST", "/payments/"+p.ID+"/refunds", `{"amount_minor":2500}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("full refund: %d %s", rec.Code, rec.Body)
	}
	got = decode[paymentResponse](t, rec)
	if got.Status != "REFUNDED" || got.RefundedMinor != 5000 || got.RemainingMinor != 0 || len(got.Refunds) != 3 {
		t.Fatalf("after full refund %+v", got)
	}
}

func TestAllPaymentEndpointsIncludeMinorFields(t *testing.T) {
	a := newTestAPI(t)

	assertMinorKeys := func(t *testing.T, raw map[string]any, wantRefunds int) {
		t.Helper()
		for _, k := range []string{"amount", "amount_minor", "fee", "fee_minor", "refunded_amount", "refunded_minor", "remaining_amount", "remaining_minor"} {
			if _, ok := raw[k]; !ok {
				t.Fatalf("missing key %q in %v", k, raw)
			}
		}
		refs, ok := raw["refunds"].([]any)
		if !ok || len(refs) != wantRefunds {
			t.Fatalf("refunds = %v, want len %d", raw["refunds"], wantRefunds)
		}
		for i, item := range refs {
			rm := item.(map[string]any)
			for _, k := range []string{"id", "amount", "amount_minor", "created_at"} {
				if _, ok := rm[k]; !ok {
					t.Fatalf("refund[%d] missing key %q in %v", i, k, rm)
				}
			}
		}
	}

	// 1. POST /payments (tiny amount so fee_minor == 0 and refunded_minor == 0)
	rec := a.do("POST", "/payments", `{"merchant_id":"m_1","amount_minor":1,"currency":"USD"}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("create: %d %s", rec.Code, rec.Body)
	}
	raw := decode[map[string]any](t, rec)
	assertMinorKeys(t, raw, 0)
	id := raw["id"].(string)

	// 2. GET /payments/{id}
	assertMinorKeys(t, decode[map[string]any](t, a.do("GET", "/payments/"+id, "")), 0)

	// 3. POST /payments/{id}/authorize
	assertMinorKeys(t, decode[map[string]any](t, a.do("POST", "/payments/"+id+"/authorize", "")), 0)

	// 4. POST /payments/{id}/capture
	assertMinorKeys(t, decode[map[string]any](t, a.do("POST", "/payments/"+id+"/capture", "")), 0)

	// 5. POST /payments/{id}/refunds (full refund so remaining_minor == 0)
	assertMinorKeys(t, decode[map[string]any](t, a.do("POST", "/payments/"+id+"/refunds", `{"amount_minor":1}`)), 1)

	// 6. POST /payments/{id}/decline on a second payment
	rec2 := a.do("POST", "/payments", `{"merchant_id":"m_1","amount_minor":500,"currency":"USD"}`)
	id2 := decode[paymentResponse](t, rec2).ID
	assertMinorKeys(t, decode[map[string]any](t, a.do("POST", "/payments/"+id2+"/decline", `{"reason":"nope"}`)), 0)

	// 7. GET /merchants/{merchantID}/payments (list)
	listRaw := decode[map[string]any](t, a.do("GET", "/merchants/m_1/payments", ""))
	items := listRaw["data"].([]any)
	if len(items) != 2 {
		t.Fatalf("list len = %d", len(items))
	}
	assertMinorKeys(t, items[0].(map[string]any), 1)
	assertMinorKeys(t, items[1].(map[string]any), 0)
}

