134	func resolveAmount(amount *string, amountMinor *int64, currency string) (money.Amount, error) {
135		switch {
136		case amount == nil && amountMinor == nil:
137			return money.Amount{}, fmt.Errorf("%w: amount or amount_minor is required", payment.ErrInvalidInput)
138		case amount != nil && amountMinor == nil:
139			return money.Parse(*amount, currency)
140		case amount == nil && amountMinor != nil:
141			return money.New(*amountMinor, currency)
142		default:
143			parsed, err := money.Parse(*amount, currency)
144			if err != nil {
145				return money.Amount{}, err
146			}
147			minor, err := money.New(*amountMinor, currency)
148			if err != nil {
149				return money.Amount{}, err
150			}
151			if parsed.Minor != minor.Minor {
152				return money.Amount{}, fmt.Errorf("%w: amount %q and amount_minor %d do not match", payment.ErrInvalidInput, *amount, *amountMinor)
153			}
154			return parsed, nil
155		}
156	}
