158	func decodeJSON(r *http.Request, dst any) error {
159		dec := json.NewDecoder(io.LimitReader(r.Body, maxBodyBytes))
160		dec.DisallowUnknownFields()
161		if err := dec.Decode(dst); err != nil {
162			return fmt.Errorf("%w: malformed JSON body: %v", payment.ErrInvalidInput, err)
163		}
164		return nil
165	}
166	
167	func writeJSON(w http.ResponseWriter, status int, body any) {
168		w.Header().Set("Content-Type", "application/json")
169		w.WriteHeader(status)
170		_ = json.NewEncoder(w).Encode(body)
171	}
